-- Actual TALK targets choose the speaker when a victim is a Creature.
-- Keep Fleshripper aggro/death text on101778 for all actual invokers.
-- Native205 already resolves player/pet/guardian owners; preserve original credit, thresholds, loot and return.
SET @fleshripper_speakers_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
